package com.fincore.fincore.budget; import java.math.BigDecimal; import java.time.*; import com.fincore.fincore.user.User; import jakarta.persistence.*; @Entity @Table(name="budgets") public class Budget{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=80)private String category;@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;@Column(nullable=false)private LocalDate month;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Budget(){}public Budget(String c,BigDecimal a,LocalDate m,User u){category=c;amount=a;month=m;user=u;}@PrePersist void c(){var n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void u(){updatedAt=Instant.now();}public Long getId(){return id;}public String getCategory(){return category;}public BigDecimal getAmount(){return amount;}public LocalDate getMonth(){return month;}public void setAmount(BigDecimal a){amount=a;}}
